  1	// Shared window-position helpers. Both the engine (tick loop) and the physics
  2	// module (throw/fall) need to read and write the pet window's logical position;
  3	// centralizing it keeps the DPI conversion in one place and avoids two copies
  4	// of the same `outerPosition / scaleFactor` dance drifting apart.
  5	
  6	import { getCurrentWindow } from "@tauri-apps/api/window";
  7	import { LogicalPosition } from "@tauri-apps/api/dpi";
  8	import type { Point } from "./types";
  9	
 10	const win = getCurrentWindow();
 11	
 12	let cachedLogicalPos: Point | null = null;
 13	let cacheGeneration = 0;
 14	let pendingPositionRead: Promise<Point | null> | null = null;
 15	let pendingMovedPosition: Promise<void> | null = null;
 16	let trackingStarted = false;
 17	let pendingTracking: Promise<void> | null = null;
 18	
 19	function copyPoint(pos: Point): Point {
 20	  return { x: pos.x, y: pos.y };
 21	}
 22	
 23	function refreshMovedPosition(physical: Point): void {
 24	  const generationAtMove = ++cacheGeneration;
 25	  cachedLogicalPos = null;
 26	  let update: Promise<void>;
 27	  update = win.scaleFactor()
 28	    .then((scaleFactor) => {
 29	      if (generationAtMove !== cacheGeneration) return;
 30	      cachedLogicalPos = {
 31	        x: physical.x / scaleFactor,
 32	        y: physical.y / scaleFactor,
 33	      };
 34	    })
 35	    .catch(() => {
 36	      // Keep the cache invalid; the regular reader retries when it is needed.
 37	    })
 38	    .finally(() => {
 39	      if (pendingMovedPosition === update) pendingMovedPosition = null;
 40	    });
 41	  pendingMovedPosition = update;
 42	}
 43	
 44	function startPositionTracking(): void {
 45	  if (trackingStarted || pendingTracking) return;
 46	  const movedRegistration = win.onMoved(({ payload }) => {
 47	    refreshMovedPosition(payload);
 48	  });
 49	  const scaleRegistration = win.onScaleChanged(() => {
 50	    cacheGeneration += 1;
 51	    cachedLogicalPos = null;
 52	  });
 53	  pendingTracking = Promise.allSettled([movedRegistration, scaleRegistration])
 54	    .then(([moved, scale]) => {
 55	      if (moved.status === "fulfilled" && scale.status === "fulfilled") {
 56	        trackingStarted = true;
 57	        return;
 58	      }
 59	      if (moved.status === "fulfilled") moved.value();
 60	      if (scale.status === "fulfilled") scale.value();
 61	    })
 62	    .finally(() => {
 63	      pendingTracking = null;
 64	    });
 65	}
 66	
 67	/// Current window position in LOGICAL pixels (DPI-divided). Returns null if the
 68	/// window or scaleFactor can't be read (e.g. window closing).
 69	export async function currentLogicalPos(): Promise<Point | null> {
 70	  startPositionTracking();
 71	  if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 72	  if (pendingMovedPosition) {
 73	    await pendingMovedPosition;
 74	    if (cachedLogicalPos) return copyPoint(cachedLogicalPos);
 75	  }
 76	  if (!pendingPositionRead) {
 77	    const generationAtReadStart = cacheGeneration;
 78	    pendingPositionRead = (async () => {
 79	      try {
 80	        const sf = await win.scaleFactor();
 81	        const p = await win.outerPosition();
 82	        if (generationAtReadStart !== cacheGeneration) {
 83	          return cachedLogicalPos ? copyPoint(cachedLogicalPos) : null;
 84	        }
 85	        cachedLogicalPos = { x: p.x / sf, y: p.y / sf };
 86	        return copyPoint(cachedLogicalPos);
 87	      } catch {
 88	        return null;
 89	      } finally {
 90	        pendingPositionRead = null;
 91	      }
 92	    })();
 93	  }
 94	  const pos = await pendingPositionRead;
 95	  return pos ? copyPoint(pos) : null;
 96	}
 97	
 98	/// Move the window to a logical-pixel position. Caller is responsible for
 99	/// clamping to the work area first.
100	export async function setLogical(pos: Point): Promise<void> {
101	  await win.setPosition(new LogicalPosition(pos.x, pos.y));
102	  cacheGeneration += 1;
103	  cachedLogicalPos = copyPoint(pos);
104	}
