    94	}
    95	
    96	fn write_desktop_pets_visible(visible: bool) {
    97	    if let Some(path) = desktop_pets_visible_file() {
    98	        if let Some(parent) = path.parent() {
    99	            let _ = std::fs::create_dir_all(parent);
   100	        }
   101	        let _ = std::fs::write(path, if visible { "1" } else { "0" });
   102	    }
   103	}
   104	
   105	/// Append a line to %APPDATA%/DesktopPet/debug.log for field diagnostics.
   106	fn dlog(msg: &str) {
   107	    if let Some(path) = dirs::config_dir().map(|dir| dir.join("DesktopPet").join("debug.log")) {
   108	        if let Some(parent) = path.parent() {
   109	            let _ = std::fs::create_dir_all(parent);
   110	        }
   111	        if let Ok(mut file) = std::fs::OpenOptions::new().create(true).append(true).open(path) {
   112	            use std::io::Write;
   113	            let timestamp = std::time::SystemTime::now()
   114	                .duration_since(std::time::UNIX_EPOCH)
   115	                .map(|duration| duration.as_secs())
   116	                .unwrap_or(0);
   117	            let _ = writeln!(file, "[{timestamp}] {msg}");
   118	        }
   119	    }
   120	}
