   125	}
   126	
   127	/// Report a pet window's opaque rectangle (physical px, window-relative) so
   128	/// empty transparent areas of that overlay let clicks pass through to apps
   129	/// below. Each pet window registers under its own label so multi-pet mode
   130	/// doesn't have one window overwrite another's click-through rect.
   131	#[tauri::command]
   132	fn set_hit_rect(app: tauri::AppHandle, label: String, x: f64, y: f64, w: f64, h: f64) {
   133	    if !is_pet_window(&label) {
   134	        return;
   135	    }
   136	    if let Some(state) = app.try_state::<Mutex<HitRectMap>>() {
   137	        if let Ok(mut m) = state.lock() {
   138	            m.insert(label, HitRect { x, y, w, h });
   139	        }
   140	    }
   141	}
