   249	fn default_pet_position(app: &tauri::AppHandle, index: usize) -> (f64, f64) {
   250	    let (width, height) = primary_work_area(app);
   251	    let x = (width - 280.0 - index as f64 * 48.0).max(20.0);
   252	    let y = (height - 380.0 + index as f64 * 32.0).max(20.0);
   253	    (x, y)
   254	}
