   256	fn logical_position_for_physical(app: &tauri::AppHandle, x: i32, y: i32) -> (f64, f64) {
   257	    let scale_factor = app.available_monitors()
   258	        .ok()
   259	        .and_then(|monitors| monitors.into_iter().find(|monitor| {
   260	            let position = monitor.position();
   261	            let size = monitor.size();
   262	            x >= position.x
   263	                && x < position.x + size.width as i32
   264	                && y >= position.y
   265	                && y < position.y + size.height as i32
   266	        }))
   267	        .map(|monitor| monitor.scale_factor())
   268	        .unwrap_or(1.0);
   269	    (x as f64 / scale_factor, y as f64 / scale_factor)
   270	}
