   272	fn build_desktop_pet_window(
   273	    app: &tauri::AppHandle,
   274	    instance: &DesktopPetWindow,
   275	    index: usize,
   276	) -> Result<(), String> {
   277	    let label = pet_window_label(&instance.id);
   278	    if let Some(window) = app.get_webview_window(&label) {
   279	        if instance.visible && read_desktop_pets_visible() {
   280	            window.show().map_err(|error| error.to_string())?;
   281	        } else {
   282	            window.hide().map_err(|error| error.to_string())?;
   283	        }
   284	        return Ok(());
   285	    }
   286	
   287	    let url = format!("index.html?pet={}", instance.id);
   288	    let mut builder = WebviewWindowBuilder::new(app, &label, WebviewUrl::App(url.into()))
   289	        .title("DesktopPet")
   290	        .inner_size(260.0, 320.0)
   291	        .transparent(true)
   292	        .decorations(false)
   293	        .always_on_top(true)
   294	        .skip_taskbar(true)
   295	        .resizable(false)
   296	        .shadow(false)
   297	        .focused(false)
   298	        .visible(instance.visible && read_desktop_pets_visible());
   299	    builder = match saved_pet_position(app, &instance.id) {
   300	        Some((x, y)) => {
   301	            let (x, y) = logical_position_for_physical(app, x, y);
   302	            builder.position(x, y)
   303	        }
   304	        None => {
   305	            let (x, y) = default_pet_position(app, index);
   306	            builder.position(x, y)
   307	        }
   308	    };
   309	    builder.build().map_err(|error| error.to_string())?;
   310	    Ok(())
   311	}
