   363	/// The floating ball window label. A single instance lives on the desktop as a
   364	/// stable click target (left = bubble menu, right = Settings) so the user
   365	/// doesn't have to chase a roaming pet.
   366	const FLOATING_BALL_LABEL: &str = "floating-ball";
   367	// The visible orb is 56×56, but the window is 80×80 so shadows and hover
   368	// scale are not clipped by the square window edges.
   369	const BALL_W: f64 = 80.0;
   370	const BALL_H: f64 = 80.0;
   371	
   372	fn ball_pos_file() -> Option<std::path::PathBuf> {
   373	    dirs::config_dir().map(|d| d.join("DesktopPet").join("ball-pos"))
   374	}
   375	fn read_ball_pos() -> Option<(f64, f64)> {
   376	    let s = std::fs::read_to_string(ball_pos_file()?).ok()?;
   377	    let (a, b) = s.trim().split_once(',')?;
   378	    Some((a.trim().parse().ok()?, b.trim().parse().ok()?))
   379	}
   380	fn write_ball_pos(x: f64, y: f64) {
   381	    if let Some(p) = ball_pos_file() {
   382	        if let Some(d) = p.parent() { let _ = std::fs::create_dir_all(d); }
   383	        let _ = std::fs::write(p, format!("{x},{y}"));
   384	    }
   385	}
   386	fn ball_visible_file() -> Option<std::path::PathBuf> {
   387	    dirs::config_dir().map(|d| d.join("DesktopPet").join("ball-visible"))
   388	}
   389	fn read_ball_visible() -> bool {
   390	    ball_visible_file()
   391	        .and_then(|p| std::fs::read_to_string(p).ok())
   392	        .map(|s| s.trim() != "0")
   393	        .unwrap_or(true)
