   431	/// Persist the floating ball's drop position after an OS-level drag.
   432	/// This deliberately avoids a second set_position call, which can flash on
   433	/// Windows transparent windows during the drag-end compositor update.
   434	#[tauri::command]
   435	fn persist_floating_ball_position(app: tauri::AppHandle) {
   436	    let Some(win) = app.get_webview_window(FLOATING_BALL_LABEL) else {
   437	        return;
