   439	    let Ok(pos) = win.outer_position() else {
   440	        return;
   441	    };
   442	    let Ok(scale_factor) = win.scale_factor() else {
   443	        return;
   444	    };
   445	    write_ball_pos(pos.x as f64 / scale_factor, pos.y as f64 / scale_factor);
   446	}
