   328	/// Reconciles every persistent desktop-pet instance with a single frontend
   329	/// source of truth. Window labels are opaque IDs, never sprite slugs or projects.
   330	#[tauri::command]
   331	async fn sync_desktop_pet_windows(
   332	    app: tauri::AppHandle,
   333	    pets: Vec<DesktopPetWindow>,
   334	) -> Result<(), String> {
   335	    if pets.len() > MAX_DESKTOP_PETS {
   336	        return Err(format!("desktop pet limit is {MAX_DESKTOP_PETS}"));
   337	    }
   338	    let mut ids = std::collections::HashSet::new();
   339	    for pet in &pets {
   340	        if !valid_pet_id(&pet.id) || !ids.insert(&pet.id) {
   341	            return Err("invalid or duplicate desktop pet id".into());
   342	        }
   343	    }
   344	    let generation = app
   345	        .try_state::<Mutex<DesktopPetSyncState>>()
   346	        .and_then(|state| state.lock().ok().map(|mut state| {
   347	            state.generation = state.generation.wrapping_add(1);
   348	            state.generation
   349	        }))
   350	        .ok_or("desktop pet sync state unavailable")?;
   351	    std::thread::spawn(move || {
   352	        let is_current = app
   353	            .try_state::<Mutex<DesktopPetSyncState>>()
   354	            .and_then(|state| state.lock().ok().map(|state| state.generation == generation))
   355	            .unwrap_or(false);
   356	        if is_current {
   357	            sync_desktop_pet_windows_impl(app, pets);
   358	        }
   359	    });
   360	    Ok(())
   361	}
